insert into public.questions (id, author_id, species_id, title, body, status, answer_count, is_demo, created_at) select '07bb47f6-88df-5d8b-8510-9b0615f0f3cb', '9d7baf9e-8e0f-53e7-8091-d8d9a5226b24', id, 'আমার বিড়াল দুই দিন ধরে খাচ্ছে না, কী করব?', 'মিশুর বয়স ৩ বছর। দুই দিন ধরে খাবার খাচ্ছে না, শুধু পানি খাচ্ছে। বমি করেনি।', 'answered', 1, true, now() - interval '29 hours' from public.species where slug = 'cat' on conflict (id) do nothing;
insert into public.answers (id, question_id, provider_id, body, helpful_count) values ('90f72a8a-c825-5a5b-a688-14f1a126de56', '07bb47f6-88df-5d8b-8510-9b0615f0f3cb', '5f0c5b16-f261-57b4-af4c-7cc800966d25', 'দুই দিন না খাওয়া বিড়ালের জন্য ঝুঁকিপূর্ণ (লিভারের সমস্যা হতে পারে)। আজই একজন ভেটকে দেখান। ততক্ষণ পছন্দের ভেজা খাবার একটু গরম করে দিন, জোর করে খাওয়াবেন না।', 21) on conflict (id) do nothing;
insert into public.questions (id, author_id, species_id, title, body, status, answer_count, is_demo, created_at) select '077600c5-e40c-599e-967f-1f38c2d23154', '1c32f1c0-37ad-5194-9672-f7f3204a6a7a', id, 'How often should I deworm my puppy?', 'My Labrador puppy is 10 weeks old. The breeder said once, but I''m not sure.', 'answered', 1, true, now() - interval '165 hours' from public.species where slug = 'dog' on conflict (id) do nothing;
insert into public.answers (id, question_id, provider_id, body, helpful_count) values ('de0bac4a-edf9-5d24-97e1-1ed8fcfc7e71', '077600c5-e40c-599e-967f-1f38c2d23154', '8dabe98f-386d-55f6-92ed-bd9b7ab1cebc', 'Puppies need deworming every 2 weeks until 12 weeks old, then monthly until 6 months, then every 3 months. Use a vet-recommended dose by weight.', 34) on conflict (id) do nothing;
insert into public.questions (id, author_id, species_id, title, body, status, answer_count, is_demo, created_at) select '8594d128-6557-5a69-b090-50058f6fdf39', '9d7baf9e-8e0f-53e7-8091-d8d9a5226b24', id, 'বিড়ালের ভ্যাকসিন কখন দিতে হয়?', 'নতুন বিড়ালছানা এনেছি, বয়স ২ মাস। কোন ভ্যাকসিন কখন দেব?', 'answered', 1, true, now() - interval '157 hours' from public.species where slug = 'cat' on conflict (id) do nothing;
insert into public.answers (id, question_id, provider_id, body, helpful_count) values ('6073a094-aacc-556c-ad0a-103ae73d020e', '8594d128-6557-5a69-b090-50058f6fdf39', '7a4a52bf-0f1d-59e4-b321-86651a50f708', '৮–৯ সপ্তাহে প্রথম Tricat, ৩–৪ সপ্তাহ পর বুস্টার, ১২ সপ্তাহের পর র‍্যাবিস। তারপর বছরে একবার। ভ্যাকসিনের আগে কৃমিনাশক দিয়ে নিন।', 14) on conflict (id) do nothing;
insert into public.questions (id, author_id, species_id, title, body, status, answer_count, is_demo, created_at) select 'ff6fb597-482f-5fb1-b707-f91bc88702bb', '1c32f1c0-37ad-5194-9672-f7f3204a6a7a', id, 'Budgie sitting fluffed up all day', 'My budgie is quiet and fluffed up since morning. Is it cold?', 'answered', 1, true, now() - interval '41 hours' from public.species where slug = 'bird' on conflict (id) do nothing;
insert into public.answers (id, question_id, provider_id, body, helpful_count) values ('3f46e8a8-bf5e-570b-b51c-290f8cd9a236', 'ff6fb597-482f-5fb1-b707-f91bc88702bb', '01ecb734-7b97-5b49-87ce-82bf353f3c62', 'A fluffed-up, quiet budgie is often unwell, not just cold. Keep it warm (around 30°C), offer food and water nearby, and see an avian vet today if it doesn''t improve.', 25) on conflict (id) do nothing;
